-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , ia AS (SELECT order_id,count(*) itens,sum(price) price,sum(freight_value) freight_value FROM i GROUP BY 1), ga AS (SELECT order_id,count(*) pagamentos,sum(payment_value) payment_value FROM g GROUP BY 1), r AS (SELECT p.order_id,p.order_status,p.mes,ia.itens,ga.pagamentos,ia.price,ia.freight_value,ga.payment_value,ga.payment_value-ia.price-ia.freight_value diferenca FROM p LEFT JOIN ia USING(order_id) LEFT JOIN ga USING(order_id)) SELECT CASE WHEN grouping(order_status)=0 THEN 'status' WHEN grouping(mes)=0 THEN 'mes' ELSE 'total' END nivel,order_status,mes,count(*) pedidos,count(*) FILTER(WHERE itens IS NULL) sem_itens,count(*) FILTER(WHERE pagamentos IS NULL) sem_pagamentos,count(diferenca) comparaveis,count(*) FILTER(WHERE diferenca<>0) diferencas_nao_zero,count(*) FILTER(WHERE abs(diferenca)>0.01) divergencias,sum(price) price,sum(freight_value) freight_value,sum(payment_value) payment_value,sum(diferenca) diferenca_comparaveis FROM r GROUP BY GROUPING SETS((),(order_status),(mes)) ORDER BY 1,2,3;
